"""Consistent JSON error envelope for the whole API."""
from flask import jsonify
from werkzeug.exceptions import HTTPException


class APIError(Exception):
    """Application-level error carrying an HTTP status and machine-readable code."""

    status_code = 400
    error_code = "bad_request"

    def __init__(self, message, status_code=None, error_code=None, details=None):
        super().__init__(message)
        self.message = message
        if status_code is not None:
            self.status_code = status_code
        if error_code is not None:
            self.error_code = error_code
        self.details = details


class ValidationAPIError(APIError):
    status_code = 422
    error_code = "validation_error"


class AuthError(APIError):
    status_code = 401
    error_code = "unauthorized"


class ForbiddenError(APIError):
    status_code = 403
    error_code = "forbidden"


class NotFoundError(APIError):
    status_code = 404
    error_code = "not_found"


class ConflictError(APIError):
    status_code = 409
    error_code = "conflict"


class RateLimitError(APIError):
    status_code = 429
    error_code = "rate_limited"


def _envelope(code, message, status, details=None):
    body = {"error": {"code": code, "message": message}}
    if details:
        body["error"]["details"] = details
    resp = jsonify(body)
    resp.status_code = status
    return resp


def register_error_handlers(app):
    @app.errorhandler(APIError)
    def handle_api_error(err):
        resp = _envelope(err.error_code, err.message, err.status_code, err.details)
        if isinstance(err, RateLimitError) and err.details and "retry_after" in err.details:
            resp.headers["Retry-After"] = str(err.details["retry_after"])
        return resp

    @app.errorhandler(HTTPException)
    def handle_http_exception(err):
        code = {
            400: "bad_request",
            401: "unauthorized",
            403: "forbidden",
            404: "not_found",
            405: "method_not_allowed",
            415: "unsupported_media_type",
        }.get(err.code, "http_error")
        return _envelope(code, err.description, err.code)

    @app.errorhandler(Exception)
    def handle_unexpected(err):
        app.logger.exception("Unhandled exception")
        return _envelope("internal_error", "An internal error occurred.", 500)

"""JWT-based authentication: token issuance, verification, and route guard."""
import datetime as dt
import functools
import hashlib
import hmac
import secrets
import uuid

import jwt
from flask import current_app, g, request

from .errors import AuthError

_PBKDF2_ITERATIONS = 200_000


def hash_password(password: str) -> str:
    salt = secrets.token_hex(16)
    digest = hashlib.pbkdf2_hmac(
        "sha256", password.encode(), salt.encode(), _PBKDF2_ITERATIONS
    ).hex()
    return f"pbkdf2_sha256${_PBKDF2_ITERATIONS}${salt}${digest}"


def verify_password(password: str, stored: str) -> bool:
    try:
        _algo, iterations, salt, digest = stored.split("$")
        candidate = hashlib.pbkdf2_hmac(
            "sha256", password.encode(), salt.encode(), int(iterations)
        ).hex()
        return hmac.compare_digest(candidate, digest)
    except (ValueError, AttributeError):
        return False


def _make_token(user_id: int, token_type: str, ttl_seconds: int) -> str:
    now = dt.datetime.now(dt.timezone.utc)
    payload = {
        "sub": str(user_id),
        "type": token_type,
        "iat": now,
        "exp": now + dt.timedelta(seconds=ttl_seconds),
        "jti": uuid.uuid4().hex,
    }
    return jwt.encode(
        payload,
        current_app.config["SECRET_KEY"],
        algorithm=current_app.config["JWT_ALGORITHM"],
    )


def issue_tokens(user_id: int) -> dict:
    cfg = current_app.config
    return {
        "access_token": _make_token(user_id, "access", cfg["JWT_ACCESS_TTL_SECONDS"]),
        "refresh_token": _make_token(user_id, "refresh", cfg["JWT_REFRESH_TTL_SECONDS"]),
        "token_type": "Bearer",
        "expires_in": cfg["JWT_ACCESS_TTL_SECONDS"],
    }


def decode_token(token: str, expected_type: str) -> dict:
    try:
        payload = jwt.decode(
            token,
            current_app.config["SECRET_KEY"],
            algorithms=[current_app.config["JWT_ALGORITHM"]],
            options={"require": ["sub", "exp", "iat", "type"]},
        )
    except jwt.ExpiredSignatureError:
        raise AuthError("Token has expired.", error_code="token_expired")
    except jwt.InvalidTokenError:
        raise AuthError("Invalid token.", error_code="token_invalid")
    if payload.get("type") != expected_type:
        raise AuthError(
            f"Expected a {expected_type} token.", error_code="wrong_token_type"
        )
    return payload


def _bearer_token() -> str:
    header = request.headers.get("Authorization", "")
    parts = header.split()
    if len(parts) != 2 or parts[0].lower() != "bearer":
        raise AuthError("Missing or malformed Authorization header.",
                        error_code="missing_token")
    return parts[1]


def require_auth(fn):
    """Decorator: route requires a valid access token. Sets g.current_user_id."""

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        payload = decode_token(_bearer_token(), "access")
        g.current_user_id = int(payload["sub"])
        return fn(*args, **kwargs)

    return wrapper

"""Lightweight declarative validation for JSON request bodies."""
import re

from flask import request

from .errors import ValidationAPIError

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


class Field:
    def __init__(self, type_=str, required=True, min_length=None, max_length=None,
                 pattern=None, pattern_message=None, strip=True):
        self.type_ = type_
        self.required = required
        self.min_length = min_length
        self.max_length = max_length
        self.pattern = pattern
        self.pattern_message = pattern_message
        self.strip = strip

    def validate(self, name, value, errors):
        if value is None:
            if self.required:
                errors[name] = "This field is required."
            return None
        if not isinstance(value, self.type_) or isinstance(value, bool) and self.type_ is int:
            errors[name] = f"Must be of type {self.type_.__name__}."
            return None
        if isinstance(value, str) and self.strip:
            value = value.strip()
        if self.min_length is not None and len(value) < self.min_length:
            errors[name] = f"Must be at least {self.min_length} characters long."
            return None
        if self.max_length is not None and len(value) > self.max_length:
            errors[name] = f"Must be at most {self.max_length} characters long."
            return None
        if self.pattern is not None and not self.pattern.match(value):
            errors[name] = self.pattern_message or "Invalid format."
            return None
        return value


def validate_json(schema: dict) -> dict:
    """Validate request JSON body against schema; raise 422 with per-field details."""
    data = request.get_json(silent=True)
    if data is None or not isinstance(data, dict):
        raise ValidationAPIError("Request body must be a JSON object.")

    errors = {}
    unknown = set(data) - set(schema)
    for key in unknown:
        errors[key] = "Unknown field."

    cleaned = {}
    for name, field in schema.items():
        value = field.validate(name, data.get(name), errors)
        if name not in errors and (name in data or field.required):
            cleaned[name] = value

    if errors:
        raise ValidationAPIError("Validation failed.", details=errors)
    return cleaned


# Reusable schemas
REGISTER_SCHEMA = {
    "email": Field(str, max_length=254, pattern=EMAIL_RE,
                   pattern_message="Must be a valid email address."),
    "password": Field(str, min_length=8, max_length=128, strip=False),
}

LOGIN_SCHEMA = {
    "email": Field(str, max_length=254),
    "password": Field(str, max_length=128, strip=False),
}

REFRESH_SCHEMA = {
    "refresh_token": Field(str, max_length=4096),
}

ITEM_CREATE_SCHEMA = {
    "name": Field(str, min_length=1, max_length=120),
    "description": Field(str, required=False, max_length=2000),
}

ITEM_UPDATE_SCHEMA = {
    "name": Field(str, required=False, min_length=1, max_length=120),
    "description": Field(str, required=False, max_length=2000),
}

"""Offset/limit pagination helpers with a stable response envelope."""
from flask import current_app, request, url_for

from .errors import ValidationAPIError


def get_page_args():
    def _int_arg(name, default, minimum, maximum):
        raw = request.args.get(name, default)
        try:
            value = int(raw)
        except (TypeError, ValueError):
            raise ValidationAPIError(f"Query parameter '{name}' must be an integer.")
        if not (minimum <= value <= maximum):
            raise ValidationAPIError(
                f"Query parameter '{name}' must be between {minimum} and {maximum}.")
        return value

    cfg = current_app.config
    page = _int_arg("page", 1, 1, 1_000_000)
    per_page = _int_arg("per_page", cfg["PAGINATION_DEFAULT_PER_PAGE"],
                        1, cfg["PAGINATION_MAX_PER_PAGE"])
    return page, per_page


def paginated_response(items, page, per_page, total, endpoint, **url_kwargs):
    pages = max(1, -(-total // per_page))  # ceil division

    def _link(p):
        return url_for(endpoint, page=p, per_page=per_page, **url_kwargs)

    return {
        "data": items,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "pages": pages,
        },
        "links": {
            "self": _link(page),
            "next": _link(page + 1) if page < pages else None,
            "prev": _link(page - 1) if page > 1 else None,
        },
    }

import sqlite3

from flask import g, jsonify

from ...audit import audit
from ...auth import (decode_token, hash_password, issue_tokens, require_auth,
                     verify_password)
from ...db import get_db
from ...errors import AuthError, ConflictError
from ...validation import (LOGIN_SCHEMA, REFRESH_SCHEMA, REGISTER_SCHEMA,
                           validate_json)
from . import bp


@bp.post("/auth/register")
def register():
    data = validate_json(REGISTER_SCHEMA)
    db = get_db()
    try:
        cur = db.execute(
            "INSERT INTO users (email, password_hash) VALUES (?, ?)",
            (data["email"].lower(), hash_password(data["password"])),
        )
        db.commit()
    except sqlite3.IntegrityError:
        raise ConflictError("A user with this email already exists.",
                            error_code="email_taken")
    user_id = cur.lastrowid
    g.current_user_id = user_id
    audit("user.register", resource=f"user:{user_id}",
          detail={"email": data["email"].lower()})
    return jsonify({"id": user_id, "email": data["email"].lower()}), 201


@bp.post("/auth/login")
def login():
    data = validate_json(LOGIN_SCHEMA)
    db = get_db()
    row = db.execute(
        "SELECT id, password_hash FROM users WHERE email = ?",
        (data["email"].lower(),),
    ).fetchone()
    if row is None or not verify_password(data["password"], row["password_hash"]):
        audit("auth.login_failed", detail={"email": data["email"].lower()})
        raise AuthError("Invalid email or password.", error_code="invalid_credentials")
    g.current_user_id = row["id"]
    audit("auth.login", resource=f"user:{row['id']}")
    return jsonify(issue_tokens(row["id"]))


@bp.post("/auth/refresh")
def refresh():
    data = validate_json(REFRESH_SCHEMA)
    payload = decode_token(data["refresh_token"], "refresh")
    user_id = int(payload["sub"])
    row = get_db().execute("SELECT id FROM users WHERE id = ?", (user_id,)).fetchone()
    if row is None:
        raise AuthError("Unknown user.", error_code="token_invalid")
    g.current_user_id = user_id
    audit("auth.refresh", resource=f"user:{user_id}")
    return jsonify(issue_tokens(user_id))


@bp.get("/auth/me")
@require_auth
def me():
    row = get_db().execute(
        "SELECT id, email, created_at FROM users WHERE id = ?",
        (g.current_user_id,),
    ).fetchone()
    if row is None:
        raise AuthError("Unknown user.", error_code="token_invalid")
    return jsonify(dict(row))

from flask import g, jsonify

from ...audit import audit
from ...auth import require_auth
from ...db import get_db
from ...errors import NotFoundError
from ...pagination import get_page_args, paginated_response
from ...validation import ITEM_CREATE_SCHEMA, ITEM_UPDATE_SCHEMA, validate_json
from . import bp


def _serialize(row):
    return {
        "id": row["id"],
        "name": row["name"],
        "description": row["description"],
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
    }


def _get_owned_item(item_id):
    row = get_db().execute(
        "SELECT * FROM items WHERE id = ? AND owner_id = ?",
        (item_id, g.current_user_id),
    ).fetchone()
    if row is None:
        raise NotFoundError("Item not found.")
    return row


@bp.get("/items")
@require_auth
def list_items():
    page, per_page = get_page_args()
    db = get_db()
    total = db.execute(
        "SELECT COUNT(*) AS c FROM items WHERE owner_id = ?",
        (g.current_user_id,),
    ).fetchone()["c"]
    rows = db.execute(
        "SELECT * FROM items WHERE owner_id = ? ORDER BY id LIMIT ? OFFSET ?",
        (g.current_user_id, per_page, (page - 1) * per_page),
    ).fetchall()
    return jsonify(paginated_response(
        [_serialize(r) for r in rows], page, per_page, total, "api_v1.list_items"))


@bp.post("/items")
@require_auth
def create_item():
    data = validate_json(ITEM_CREATE_SCHEMA)
    db = get_db()
    cur = db.execute(
        "INSERT INTO items (owner_id, name, description) VALUES (?, ?, ?)",
        (g.current_user_id, data["name"], data.get("description") or ""),
    )
    db.commit()
    row = _get_owned_item(cur.lastrowid)
    audit("item.create", resource=f"item:{row['id']}", detail={"name": row["name"]})
    return jsonify(_serialize(row)), 201


@bp.get("/items/<int:item_id>")
@require_auth
def get_item(item_id):
    return jsonify(_serialize(_get_owned_item(item_id)))


@bp.patch("/items/<int:item_id>")
@require_auth
def update_item(item_id):
    row = _get_owned_item(item_id)
    data = validate_json(ITEM_UPDATE_SCHEMA)
    if not data:
        return jsonify(_serialize(row))
    db = get_db()
    db.execute(
        "UPDATE items SET name = ?, description = ?, updated_at = datetime('now') "
        "WHERE id = ?",
        (data.get("name", row["name"]),
         data.get("description", row["description"]),
         item_id),
    )
    db.commit()
    updated = _get_owned_item(item_id)
    audit("item.update", resource=f"item:{item_id}", detail={"fields": sorted(data)})
    return jsonify(_serialize(updated))


@bp.delete("/items/<int:item_id>")
@require_auth
def delete_item(item_id):
    _get_owned_item(item_id)
    db = get_db()
    db.execute("DELETE FROM items WHERE id = ?", (item_id,))
    db.commit()
    audit("item.delete", resource=f"item:{item_id}")
    return "", 204
